            var eigenvalues = [3.20, 1.80, 0.60, 0.25, 0.10, 0.05];
            var total = 6.0;
            var cumul = 0;
            var rows = [];
            for (var i = 0; i < eigenvalues.length; i++) {
                cumul += eigenvalues[i];
                rows.push([
                    '\u03BB' + (i + 1),
                    eigenvalues[i].toFixed(2),
                    (eigenvalues[i] / total * 100).toFixed(1) + '%',
                    (cumul / total * 100).toFixed(1) + '%'
                ]);
            }
            return this._renderDataTable(
                [t('mod2_component'), t('mod2_eigenvalue'), t('mod2_variance'), t('mod2_cumulative')],
                rows
            );
        }

        _matrixModule3() {
