        _matrixModule5() {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var sv = [10.0, 5.0, 2.0, 0.5, 0.1];
            var totalEnergy = 0;
            for (var i = 0; i < sv.length; i++) totalEnergy += sv[i] * sv[i];
            var cumul = 0;
            var rows = [];
            for (var i = 0; i < sv.length; i++) {
                cumul += sv[i] * sv[i];
                rows.push([
                    '\u03C3' + (i + 1),
                    sv[i].toFixed(1),
                    (sv[i] * sv[i]).toFixed(2),
                    (cumul / totalEnergy * 100).toFixed(1) + '%'
                ]);
            }
            return this._renderDataTable(
                [t('mod5_sv'), t('mod5_value'), t('mod5_energy'), t('mod5_cumulative')],
