        // ── Dynamic UI ───────────────────────────────────────────
        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.MODULES.length - 1);
            var mod = this.MODULES[idx];
            var t = window.mySimulation.t.bind(window.mySimulation);

            var titleEl = document.getElementById('moduleTitle');
            if (titleEl) titleEl.textContent = t(mod.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(mod.briefKey);

            var matrixEl = document.getElementById('matrixDisplay');
            if (matrixEl && mod.matrixFn && typeof this[mod.matrixFn] === 'function') {
                matrixEl.innerHTML = this[mod.matrixFn]();
            }

            var input1 = document.getElementById('input1');
            var input1Label = document.getElementById('input1Label');
            var input1Hint = document.getElementById('input1Hint');
            if (input1) {
                input1.min = mod.input1Min;
                input1.max = mod.input1Max;
                input1.step = mod.input1Step;
                input1.value = mod.input1Default;
            }
            if (input1Label) input1Label.textContent = t(mod.input1Key);
            if (input1Hint) input1Hint.textContent = t(mod.input1Hint);

            var input2Group = document.getElementById('input2Group');
            var input2 = document.getElementById('input2');
            var input2Label = document.getElementById('input2Label');
            var input2Hint = document.getElementById('input2Hint');
            if (input2Group) input2Group.style.display = mod.input2Visible ? 'block' : 'none';
            if (mod.input2Visible && input2) {
                input2.min = mod.input2Min;
                input2.max = mod.input2Max;
                input2.step = mod.input2Step;
                input2.value = mod.input2Default;
            }
            if (mod.input2Visible && input2Label) input2Label.textContent = t(mod.input2Key);
            if (mod.input2Visible && input2Hint) input2Hint.textContent = t(mod.input2Hint);

            var preview = document.getElementById('livePreview');
            if (preview) preview.innerHTML = '';

            var feedback = document.getElementById('feedbackPanel');
            if (feedback) feedback.style.display = 'none';
            this._updateLivePreview();
        }

        // ── Calculation helpers ──────────────────────────────────
        _calcModule1(d) {
            var w = [d.input1 / 100, d.input2 / 100, 0];
            w[2] = Math.max(0, 1 - w[0] - w[1]);
            var mu = [0.12, 0.04, 0.08];
            var cov = [
                [0.0400, 0.0060, 0.0120],
                [0.0060, 0.0025, 0.0030],
                [0.0120, 0.0030, 0.0225]
            ];
            var portReturn = 0;
            for (var i = 0; i < 3; i++) portReturn += w[i] * mu[i];
            var portVar = 0;
            for (var i = 0; i < 3; i++) {
                for (var j = 0; j < 3; j++) {
                    portVar += w[i] * w[j] * cov[i][j];
                }
            }
            var portRisk = Math.sqrt(Math.max(0, portVar));
            var rf = 0.02;
            var sharpe = portRisk > 0 ? (portReturn - rf) / portRisk : 0;
            var score = Math.min(20, Math.round(sharpe / 0.55 * 20));
            return {
                portReturn: portReturn,
                portRisk: portRisk,
                sharpe: sharpe,
                weights: [w[0], w[1], w[2]],
                score: Math.max(0, score)
            };
        }

        _calcModule2(d) {
            var eigenvalues = [3.20, 1.80, 0.60, 0.25, 0.10, 0.05];
            var total = 6.0;
            var k = Math.max(1, Math.min(6, d.input1));
            var explained = 0;
            for (var i = 0; i < k; i++) explained += eigenvalues[i];
            var ratio = explained / total;
            var score = 0;
            if (k === 2) score = 20;
            else if (k === 3) score = 15;
            else if (k === 1) score = 10;
            else if (k === 4) score = 8;
            else score = 5;
            return {
                k: k,
                explainedVariance: ratio,
                infoLoss: 1 - ratio,
                score: score
            };
        }

        _calcModule3(d) {
            var r = d.input1 / 100;
            var q = d.input2 / 100;
            var P = [
                [0.10, 0.70, 0.20],
                [0.00, r,    1 - r],
                [q,    0.00, 1 - q]
            ];
            var state_vec = [1.0, 0.0, 0.0];
            for (var iter = 0; iter < 100; iter++) {
                var next = [0, 0, 0];
                for (var j = 0; j < 3; j++) {
                    for (var i = 0; i < 3; i++) {
                        next[j] += state_vec[i] * P[i][j];
                    }
                }
                state_vec = next;
            }
            var activeRate = state_vec[1];
            var score = Math.min(20, Math.round(activeRate / 0.778 * 20));
            return {
                steadyNew: state_vec[0],
                steadyActive: state_vec[1],
                steadyChurned: state_vec[2],
                score: Math.max(0, score)
            };
        }

        _calcModule4(d) {
            var d1 = d.input1;
            var d2 = d.input2;
            var det = 0.61;
            var inv00 = 0.8 / det;
            var inv01 = 0.3 / det;
            var inv10 = 0.1 / det;
            var inv11 = 0.8 / det;
            var x1 = inv00 * d1 + inv01 * d2;
            var x2 = inv10 * d1 + inv11 * d2;
            var target1 = 600;
            var target2 = 500;
            var dist = Math.sqrt(Math.pow(x1 - target1, 2) + Math.pow(x2 - target2, 2));
            var score = Math.max(0, Math.min(20, Math.round(20 * Math.max(0, 1 - dist / 400))));
            return {
                totalOutput1: x1,
                totalOutput2: x2,
                target1: target1,
                target2: target2,
                distance: dist,
                score: score
            };
        }

        _calcModule5(d) {
            var sv = [10.0, 5.0, 2.0, 0.5, 0.1];
            var totalEnergy = 0;
            for (var i = 0; i < sv.length; i++) totalEnergy += sv[i] * sv[i];
            var k = Math.max(1, Math.min(5, d.input1));
            var captured = 0;
            for (var i = 0; i < k; i++) captured += sv[i] * sv[i];
            var accuracy = captured / totalEnergy;
            var complexityCost = k * 3;
            var efficiencyScore = accuracy * 100 - complexityCost;
            var score;
            if (k === 2) score = 20;
            else if (k === 3) score = 17;
            else if (k === 1) score = 12;
            else if (k === 4) score = 10;
            else score = 7;
            return {
                k: k,
                accuracy: accuracy,
                complexityCost: complexityCost,
                efficiencyScore: efficiencyScore,
                score: score
            };
        }

        // ── Required adapter methods ─────────────────────────────
        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    lastModuleScore: 0,
                    lastMetric: '—',
                    scoreHistory: [],
                    moduleNames: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    input1: 33,
                    input2: 33
                };
            }
            this._updateBriefing(state);
            this._bindLivePreview();
        }

        validateDecisions(decisions) {
            var input1El = document.getElementById('input1');
            if (input1El) decisions.input1 = parseFloat(input1El.value);

            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, this.MODULES.length - 1);
            var mod = this.MODULES[idx];

            if (isNaN(decisions.input1) || decisions.input1 < mod.input1Min || decisions.input1 > mod.input1Max) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('validation_range', {min: mod.input1Min, max: mod.input1Max}), 'warning'
                );
                return false;
            }

            if (mod.input2Visible) {
                var input2El = document.getElementById('input2');
                if (input2El) decisions.input2 = parseFloat(input2El.value);
                if (isNaN(decisions.input2) || decisions.input2 < mod.input2Min || decisions.input2 > mod.input2Max) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('validation_range', {min: mod.input2Min, max: mod.input2Max}), 'warning'
                    );
                    return false;
                }
            }

            if (idx === 0) {
                var w1 = decisions.input1 / 100;
                var w2 = decisions.input2 / 100;
                if (w1 + w2 > 1.001) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('mod1_weight_warning'), 'warning'
                    );
                    return false;
                }
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var idx = Math.min((state.currentPeriod || 1) - 1, this.MODULES.length - 1);
            var t = window.mySimulation.t.bind(window.mySimulation);

            var result;
            var metricLabel = '';
            var feedbackHtml = '';

            if (idx === 0) {
                result = this._calcModule1(d);
                metricLabel = 'Sharpe: ' + result.sharpe.toFixed(3);
                feedbackHtml = '<p>' + t('mod1_fb_return') + ': <strong>' + (result.portReturn * 100).toFixed(2) + '%</strong></p>';
                feedbackHtml += '<p>' + t('mod1_fb_risk') + ': <strong>' + (result.portRisk * 100).toFixed(2) + '%</strong></p>';
                feedbackHtml += '<p>' + t('mod1_fb_sharpe') + ': <strong>' + result.sharpe.toFixed(3) + '</strong></p>';
                feedbackHtml += '<p>' + t('mod1_fb_weights') + ': Tech=' + (result.weights[0] * 100).toFixed(0) + '%, ' + t('mod1_bonds') + '=' + (result.weights[1] * 100).toFixed(0) + '%, ' + t('mod1_realestate') + '=' + (result.weights[2] * 100).toFixed(0) + '%</p>';
            } else if (idx === 1) {
                result = this._calcModule2(d);
                metricLabel = t('mod2_explained') + ': ' + (result.explainedVariance * 100).toFixed(1) + '%';
                feedbackHtml = '<p>' + t('mod2_fb_components') + ': <strong>' + result.k + '</strong></p>';
                feedbackHtml += '<p>' + t('mod2_fb_explained') + ': <strong>' + (result.explainedVariance * 100).toFixed(1) + '%</strong></p>';
                feedbackHtml += '<p>' + t('mod2_fb_loss') + ': <strong>' + (result.infoLoss * 100).toFixed(1) + '%</strong></p>';
            } else if (idx === 2) {
                result = this._calcModule3(d);
                metricLabel = t('mod3_active') + ': ' + (result.steadyActive * 100).toFixed(1) + '%';
                feedbackHtml = '<p>' + t('mod3_fb_steady') + ':</p>';
                feedbackHtml += '<p>New: <strong>' + (result.steadyNew * 100).toFixed(1) + '%</strong> | ';
                feedbackHtml += 'Active: <strong>' + (result.steadyActive * 100).toFixed(1) + '%</strong> | ';
                feedbackHtml += 'Churned: <strong>' + (result.steadyChurned * 100).toFixed(1) + '%</strong></p>';
            } else if (idx === 3) {
                result = this._calcModule4(d);
                metricLabel = t('mod4_dist') + ': ' + result.distance.toFixed(0);
                feedbackHtml = '<p>' + t('mod4_fb_output') + ':</p>';
                feedbackHtml += '<p>' + t('mod4_mfg') + ': <strong>' + result.totalOutput1.toFixed(0) + '</strong> (' + t('mod4_target') + ': ' + result.target1 + ')</p>';
                feedbackHtml += '<p>' + t('mod4_svc') + ': <strong>' + result.totalOutput2.toFixed(0) + '</strong> (' + t('mod4_target') + ': ' + result.target2 + ')</p>';
            } else {
                result = this._calcModule5(d);
                metricLabel = t('mod5_accuracy_lbl') + ': ' + (result.accuracy * 100).toFixed(1) + '%';
                feedbackHtml = '<p>' + t('mod5_fb_rank') + ': <strong>' + result.k + '</strong></p>';
                feedbackHtml += '<p>' + t('mod5_fb_accuracy') + ': <strong>' + (result.accuracy * 100).toFixed(1) + '%</strong></p>';
                feedbackHtml += '<p>' + t('mod5_fb_efficiency') + ': <strong>' + result.efficiencyScore.toFixed(1) + '</strong></p>';
            }

            var moduleScore = result.score;

            state.domainState.scoreHistory[idx] = moduleScore;
            state.domainState.scoreHistory.length = idx + 1;
            state.domainState.moduleNames[idx] = t(this.MODULES[idx].titleKey);
            state.domainState.moduleNames.length = idx + 1;
            state.domainState.totalScore = state.domainState.scoreHistory.reduce(function (a, b) { return a + (b || 0); }, 0);
            state.domainState.lastModuleScore = moduleScore;
            state.domainState.lastMetric = metricLabel;

            // overallScore mirrors domainState.totalScore, already 0-100 across the 5 scored modules, the same total getPerformanceSummary reports at completion
            var overallScore = Math.max(0, Math.min(100, Math.round(state.domainState.totalScore)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackText = document.getElementById('feedbackText');
            if (feedbackPanel && feedbackText) {
                var cssClass = moduleScore >= 15 ? 'feedback-good' : (moduleScore >= 10 ? 'feedback-ok' : 'feedback-poor');
                feedbackPanel.className = 'linalg-sim-feedback' + (moduleScore >= 15 ? '' : (moduleScore >= 10 ? ' fb-ok' : ' fb-poor'));
                feedbackText.innerHTML = '<div class="' + cssClass + '">' + feedbackHtml + '<p><strong>' + t('score_earned') + ': ' + moduleScore + '/20</strong></p></div>';
                feedbackPanel.style.display = 'block';
            }

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 600);

            return {
                period: state.currentPeriod,
                module: idx + 1,
                moduleScore: moduleScore,
                metricLabel: metricLabel,
                totalScore: state.domainState.totalScore,
                input1: d.input1,
                input2: this.MODULES[idx].input2Visible ? d.input2 : null
            };
        }

