        getPerformanceSummary(history) {
            if (!history.length) return {};
            var total = 0;
            for (var i = 0; i < history.length; i++) {
                total += (history[i].results ? history[i].results.moduleScore : 0) || 0;
            }
            var avg = total / history.length;
            var performance = 'Beginner';
            if (total >= 60 && avg >= 12) performance = 'Proficient';
            if (total >= 80 && avg >= 16) performance = 'Expert';
            if (total >= 90 && avg >= 18) performance = 'Master';
            var insights = [];
            if (total >= 80) {
                insights.push('Outstanding grasp of linear algebra applications across finance and data science.');
            } else if (total >= 60) {
                insights.push('Solid understanding demonstrated. Review modules where you scored below 15 for deeper mastery.');
            } else {
                insights.push('Consider revisiting the theoretical foundations. Focus on the relationship between matrix operations and business outcomes.');
            }
            return {
                totalScore: total,
                maxScore: 100,
                averageScore: avg,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var idx = results.module - 1;
            var score = results.moduleScore;
            if (score >= 18) return window.mySimulation.t('hint_excellent');
            if (score >= 12) return window.mySimulation.t('hint_good');
            if (score >= 6) return window.mySimulation.t('hint_fair');
